"""Reader for the EU ledger export (semicolon-separated)."""
from meridian import text


def read_feed(path):
    """Read an EU feed: a list of {date, account, amount} rows."""
    rows = []
    with open(path, encoding="utf-8") as f:
        lines = f.read().splitlines()
    version = text.feed_format(lines)
    for line in lines:
        if not line or line.startswith("#"):
            continue
        if line.startswith("date;"):
            continue
        date, account, amount = line.split(";")
        rows.append({"date": date, "account": account, "amount": text.parse_amount(amount, version)})
    return rows
